-- ─────────────────────────────────────────────────────────────
-- 0006_invite_codes.sql — Layer-3 access gate for 1:1 chats
-- ─────────────────────────────────────────────────────────────
-- The bot is family-internal: an unknown LINE account gets nothing
-- until it types a valid invite code (generated by the admin with
-- /invite). Redemption is an atomic claim (used_by IS NULL guard),
-- so a code works exactly once. used_by doubles as the permanent
-- "this account was invited" record: the 1:1 gate checks it on
-- every message from an account that has no landlord row yet.

create table invite_codes (
  code       text primary key,          -- e.g. 'K7M3QT' (no 0/O/1/I/L)
  created_by text not null,             -- admin LINE userId
  created_at timestamptz not null default now(),
  expires_at timestamptz not null,
  used_by    text,                      -- LINE userId that redeemed it
  used_at    timestamptz
);

create index invite_codes_used_by_idx on invite_codes (used_by) where used_by is not null;
